from pathlib import Path

path = Path('/home/ubuntu/sistema-ahorro-cooperativo/client/src/pages/Home.tsx')
s = path.read_text()

s = s.replace('const [activeView, setActiveView] = useState<"overview" | "account" | "history">("overview");', 'const [activeView, setActiveView] = useState<"overview" | "account" | "history" | "admin">("overview");')
s = s.replace('const dashboard = trpc.cooperative.dashboard.useQuery(undefined, { enabled: Boolean(user) });', 'const dashboard = trpc.cooperative.dashboard.useQuery(undefined, { enabled: Boolean(user) });\n  const adminPayments = trpc.cooperative.adminPayments.useQuery(undefined, { enabled: user?.role === "admin" && activeView === "admin" });\n  const reviewPayment = trpc.cooperative.reviewPayment.useMutation();')
s = s.replace('const selectView = (view: "overview" | "account" | "history") =>', 'const selectView = (view: "overview" | "account" | "history" | "admin") =>')
s = s.replace('<button className={activeView === "history" ? "active" : ""} onClick={() => selectView("history")}><ReceiptText className="h-4 w-4" /> Historial de pagos</button>', '<button className={activeView === "history" ? "active" : ""} onClick={() => selectView("history")}><ReceiptText className="h-4 w-4" /> Historial de pagos</button>{user.role === "admin" && <><p className="sidebar-section">ADMINISTRACIÓN</p><button className={activeView === "admin" ? "active" : ""} onClick={() => selectView("admin")}><ShieldCheck className="h-4 w-4" /> Revisar comprobantes</button></>}')
s = s.replace('activeView === "overview" ? "Tu resumen" : activeView === "account" ? "Mi cuenta" : "Historial de pagos"', 'activeView === "overview" ? "Tu resumen" : activeView === "account" ? "Mi cuenta" : activeView === "history" ? "Historial de pagos" : "Revisión administrativa"')
needle = '</section>}</main>{paymentLevelId && <PaymentModal'
admin_view = '''</section>}{activeView === "admin" && <AdminReviewView data={adminPayments.data} isLoading={adminPayments.isLoading} onReview={async (paymentId, status) => { try { await reviewPayment.mutateAsync({ paymentId, status }); await adminPayments.refetch(); await utils.cooperative.dashboard.invalidate(); toast.success(status === "verified" ? "Comprobante aprobado." : "Comprobante rechazado."); } catch (error: any) { toast.error(error?.message || "No fue posible actualizar el comprobante."); } }} />}</main>{paymentLevelId && <PaymentModal'''
if needle not in s:
    raise SystemExit('admin insertion point not found')
s = s.replace(needle, admin_view)

marker = '\nexport default function Home() { return <AppShell />; }'
component = r'''
function AdminReviewView({ data, isLoading, onReview }: { data?: { payments: any[]; profiles: any[]; levels: any[] }; isLoading: boolean; onReview: (paymentId: number, status: "verified" | "rejected") => Promise<void> }) {
  const [filter, setFilter] = useState<"all" | "pending" | "verified" | "rejected">("pending");
  const profileByUser = useMemo(() => new Map((data?.profiles || []).map(profile => [profile.userId, profile])), [data?.profiles]);
  const levelById = useMemo(() => new Map((data?.levels || []).map(level => [level.id, level])), [data?.levels]);
  const payments = (data?.payments || []).filter(payment => filter === "all" || payment.status === filter);
  const pendingCount = (data?.payments || []).filter(payment => payment.status === "pending").length;
  return <section className="admin-view"><div className="admin-hero"><div><p className="eyebrow light">CENTRO DE CONTROL</p><h2>Revisión de comprobantes</h2><p>Verifica cada captura antes de confirmar el movimiento en el flujo cooperativo.</p></div><div className="admin-hero-stat"><ShieldCheck className="h-5 w-5" /><strong>{pendingCount}</strong><span>pendientes</span></div></div><div className="admin-toolbar"><div><p className="eyebrow">BANDEJA DE REVISIÓN</p><h3>Movimientos enviados</h3></div><div className="filter-tabs">{(["pending", "verified", "rejected", "all"] as const).map(value => <button key={value} className={filter === value ? "active" : ""} onClick={() => setFilter(value)}>{value === "pending" ? "Pendientes" : value === "verified" ? "Aprobados" : value === "rejected" ? "Rechazados" : "Todos"}</button>)}</div></div><div className="admin-table">{isLoading ? <div className="empty-state"><span>Preparando bandeja…</span></div> : payments.length === 0 ? <div className="empty-state"><FileCheck2 className="h-8 w-8" /><h3>{filter === "pending" ? "Todo al día" : "Sin comprobantes"}</h3><p>No hay movimientos en este estado.</p></div> : payments.map(payment => { const profile = profileByUser.get(payment.senderUserId || payment.receiverUserId); const level = levelById.get(payment.levelId); return <article className="admin-payment-card" key={payment.id}><div className="admin-payment-main"><div className={`movement-icon ${payment.direction}`} >{payment.direction === "sent" ? <ArrowUpRight className="h-4 w-4" /> : <ArrowDownLeft className="h-4 w-4" />}</div><div><strong>{profile?.fullName || `Participante #${payment.senderUserId || payment.receiverUserId || "—"}`}</strong><span>{payment.direction === "sent" ? "Pago realizado" : "Pago recibido"} · Nivel {level?.levelNumber || "—"}</span><small>{payment.note || "Sin referencia"} · {formatDate(payment.createdAt)}</small></div></div><div className="admin-payment-amount"><strong>{formatMoney(payment.amount)}</strong><Badge className={payment.status === "verified" ? "status-active" : payment.status === "rejected" ? "status-rejected" : "status-pending"}>{payment.status === "verified" ? "Aprobado" : payment.status === "rejected" ? "Rechazado" : "Pendiente"}</Badge></div><div className="admin-payment-proof">{payment.proofUrl ? <a href={payment.proofUrl} target="_blank" rel="noreferrer"><img src={payment.proofUrl} alt="Comprobante de pago" /><span>Ver captura</span></a> : <span className="no-proof"><ImagePlus className="h-4 w-4" /> Sin imagen</span>}</div>{payment.status === "pending" && <div className="admin-payment-actions"><Button size="sm" className="approve-btn" onClick={() => onReview(payment.id, "verified")}><Check className="mr-1 h-3.5 w-3.5" /> Aprobar</Button><Button size="sm" variant="outline" className="reject-btn" onClick={() => onReview(payment.id, "rejected")}><X className="mr-1 h-3.5 w-3.5" /> Rechazar</Button></div>}</article>; })}</div></section>;
}
'''
if marker not in s:
    raise SystemExit('component marker not found')
s = s.replace(marker, component + marker)
path.write_text(s)

css_path = Path('/home/ubuntu/sistema-ahorro-cooperativo/client/src/index.css')
css = css_path.read_text()
css += '''\n.admin-view { animation: rise .3s ease-out; }.admin-hero { min-height: 190px; border-radius: 22px; padding: 30px 34px; color: white; background: linear-gradient(118deg, #12233f, #254f7d); display: flex; justify-content: space-between; align-items: center; }.admin-hero h2 { margin: 0; font-size: 31px; letter-spacing: -.06em; }.admin-hero p:not(.eyebrow) { color: #b9cbe3; font-size: 12px; margin: 9px 0 0; }.admin-hero-stat { width: 112px; height: 112px; display: flex; flex-direction: column; align-items: center; justify-content: center; border-radius: 50%; background: #ffffff16; border: 1px solid #ffffff27; }.admin-hero-stat strong { font-size: 28px; line-height: 1; margin: 5px 0 2px; }.admin-hero-stat span { font-size: 9px; color: #b9cbe3; }.admin-toolbar { display: flex; justify-content: space-between; align-items: end; margin: 30px 0 16px; }.admin-toolbar h3 { margin: 0; font-size: 20px; letter-spacing: -.05em; }.filter-tabs { display: flex; gap: 4px; padding: 4px; background: #f0f2f5; border-radius: 10px; }.filter-tabs button { border: 0; background: transparent; color: #95a0ae; padding: 7px 11px; border-radius: 7px; font-size: 10px; }.filter-tabs button.active { background: #fff; color: var(--ink); box-shadow: 0 2px 7px #26364b12; font-weight: 700; }.admin-table { display: grid; gap: 9px; }.admin-payment-card { display: grid; grid-template-columns: minmax(210px, 1.4fr) .8fr 100px auto; gap: 16px; align-items: center; padding: 15px 18px; border-radius: 16px; background: #fff; box-shadow: 0 8px 22px #25345106; }.admin-payment-main { display: flex; align-items: center; gap: 10px; min-width: 0; }.admin-payment-main strong, .admin-payment-main span, .admin-payment-main small { display: block; }.admin-payment-main strong { font-size: 12px; }.admin-payment-main span { color: #748297; font-size: 10px; margin-top: 3px; }.admin-payment-main small { color: #a0aab7; font-size: 9px; margin-top: 4px; white-space: nowrap; overflow: hidden; text-overflow: ellipsis; }.admin-payment-amount strong { display: block; font-size: 15px; margin-bottom: 6px; }.admin-payment-proof a { display: flex; align-items: center; gap: 6px; color: var(--blue); font-size: 10px; text-decoration: none; }.admin-payment-proof img { width: 32px; height: 42px; object-fit: cover; border-radius: 5px; border: 1px solid #e6ebf0; }.no-proof { display: flex; align-items: center; gap: 4px; color: #a6afbb; font-size: 10px; }.admin-payment-actions { display: flex; gap: 6px; }.approve-btn { background: #0b9b83 !important; color: white !important; border: 0 !important; font-size: 10px !important; }.reject-btn { border-color: #f0d4d4 !important; color: #be5d5d !important; background: #fff !important; font-size: 10px !important; }\n@media (max-width: 900px) { .admin-payment-card { grid-template-columns: 1.4fr .8fr 90px; }.admin-payment-actions { grid-column: 1 / -1; justify-content: flex-end; } }\n@media (max-width: 620px) { .admin-hero { padding: 23px; }.admin-hero h2 { font-size: 25px; }.admin-hero-stat { width: 80px; height: 80px; }.admin-hero-stat strong { font-size: 21px; }.admin-toolbar { display: block; }.filter-tabs { margin-top: 12px; overflow: auto; }.admin-payment-card { grid-template-columns: 1fr auto; gap: 10px; }.admin-payment-proof { grid-column: 1 / 2; }.admin-payment-actions { grid-column: 2 / 3; grid-row: 2; display: grid; }.admin-payment-actions button { font-size: 9px !important; padding: 7px; } }\n'''
css_path.write_text(css)
